// The typed client of the server (src/generated/hydra-server-client.ts, generated by the SDK from the server contract) with the transport of this app: the
// request goes through apiUrl() and authFetch() like every other call, a refusal of the server is thrown as a ServerHttpError that keeps the status, and an
// answer that is not JSON is delivered as null so the readers of the app decide what to do with it. Routes are moved here from hand-written calls a few at a time.
import { HydraServerClient, type HydraRequest, type HydraTransport } from '../generated/hydra-server-client';
import { apiUrl } from './apiBase';
import { authFetch } from './session';

/** The server answered with a status that is not a success. */
export class ServerHttpError extends Error {
  readonly status: number;

  constructor(status: number) {
    super(`HTTP ${status}`);
    this.name = 'ServerHttpError';
    this.status = status;
  }
}

/** The path of the request with its query string (empty values are left out). */
export function requestUrl(request: Pick<HydraRequest, 'path' | 'query'>): string {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(request.query)) {
    if (value !== '') params.set(key, value);
  }
  const query = params.toString();
  return apiUrl(query ? `${request.path}?${query}` : request.path);
}

/** A transport over the given fetch function (the session one in the app, a stand-in in the tests). */
export function makeTransport(send: (url: string, init: RequestInit) => Promise<Response> = (url, init) => authFetch(url, init)): HydraTransport {
  return async (request) => {
    const init: RequestInit = { method: request.method };
    if (request.body !== undefined) {
      init.headers = { 'Content-Type': 'application/json' };
      init.body = JSON.stringify(request.body);
    }
    const res = await send(requestUrl(request), init);
    if (!res.ok) throw new ServerHttpError(res.status);
    return res.json().catch(() => null);
  };
}

/** The client every migrated call of the app uses. */
export const serverClient = new HydraServerClient(makeTransport());
